import base64,lzma
# Verified Berlin daily recharge feature: uploaded snapshots and midnight supplemental credit.
_berlin_recharge_source=lzma.decompress(base64.b64decode('')).decode('utf-8')
_optional='replacej("余额与每日提现通过原有功能单独上传。也兼容原正式版导出格式。",'
assert _berlin_recharge_source.count(_optional)==1
_berlin_recharge_source=_berlin_recharge_source.replace(_optional,'if "余额与每日提现通过原有功能单独上传。也兼容原正式版导出格式。" in j:\n    '+_optional)
exec(compile(_berlin_recharge_source,'berlin_daily_recharge_patch.py','exec'))
